def require_http_methods(request_method_list):
    """
    Decorator to make a view only accept particular request methods.  Usage::

        @require_http_methods(["GET", "POST"])
        def my_view(request):
            # I can assume now that only GET or POST requests make it this far
            # ...

    Note that request methods should be in uppercase.
    """

    def decorator(func):
        if iscoroutinefunction(func):

            @wraps(func)
            async def inner(request, *args, **kwargs):
                if request.method not in request_method_list:
                    response = HttpResponseNotAllowed(request_method_list)
                    log_response(
                        "Method Not Allowed (%s): %s",
                        request.method,
                        request.path,
                        response=response,
                        request=request,
                    )
                    return response
                return await func(request, *args, **kwargs)

        else:

            @wraps(func)
            def inner(request, *args, **kwargs):
                if request.method not in request_method_list:
                    response = HttpResponseNotAllowed(request_method_list)
                    log_response(
                        "Method Not Allowed (%s): %s",
                        request.method,
                        request.path,
                        response=response,
                        request=request,
                    )
                    return response
                return func(request, *args, **kwargs)

        return inner

    return decorator

def decorator(func):
    if iscoroutinefunction(func):

        @wraps(func)
        async def inner(request, *args, **kwargs):
            if request.method not in request_method_list:
                response = HttpResponseNotAllowed(request_method_list)
                log_response(
                    "Method Not Allowed (%s): %s",
                    request.method,
                    request.path,
                    response=response,
                    request=request,
                )
                return response
            return await func(request, *args, **kwargs)

    else:

        @wraps(func)
        def inner(request, *args, **kwargs):
            if request.method not in request_method_list:
                response = HttpResponseNotAllowed(request_method_list)
                log_response(
                    "Method Not Allowed (%s): %s",
                    request.method,
                    request.path,
                    response=response,
                    request=request,
                )
                return response
            return func(request, *args, **kwargs)

    return inner

def inner(request, *args, **kwargs):
    if request.method not in request_method_list:
        response = HttpResponseNotAllowed(request_method_list)
        log_response(
            "Method Not Allowed (%s): %s",
            request.method,
            request.path,
            response=response,
            request=request,
        )
        return response
    return func(request, *args, **kwargs)

def decorator(func):
    def _pre_process_request(request, *args, **kwargs):
        # Compute values (if any) for the requested resource.
        res_last_modified = None
        if last_modified_func:
            if dt := last_modified_func(request, *args, **kwargs):
                if not timezone.is_aware(dt):
                    dt = timezone.make_aware(dt, datetime.timezone.utc)
                res_last_modified = int(dt.timestamp())
        # The value from etag_func() could be quoted or unquoted.
        res_etag = etag_func(request, *args, **kwargs) if etag_func else None
        res_etag = quote_etag(res_etag) if res_etag is not None else None
        response = get_conditional_response(
            request,
            etag=res_etag,
            last_modified=res_last_modified,
        )
        return response, res_etag, res_last_modified

    def _post_process_request(request, response, res_etag, res_last_modified):
        # Set relevant headers on the response if they don't already exist
        # and if the request method is safe.
        if request.method in ("GET", "HEAD"):
            if res_last_modified and not response.has_header("Last-Modified"):
                response.headers["Last-Modified"] = http_date(res_last_modified)
            if res_etag:
                response.headers.setdefault("ETag", res_etag)

    if iscoroutinefunction(func):

        @wraps(func)
        async def inner(request, *args, **kwargs):
            response, res_etag, res_last_modified = _pre_process_request(
                request, *args, **kwargs
            )
            if response is None:
                response = await func(request, *args, **kwargs)
            _post_process_request(request, response, res_etag, res_last_modified)
            return response

    else:

        @wraps(func)
        def inner(request, *args, **kwargs):
            response, res_etag, res_last_modified = _pre_process_request(
                request, *args, **kwargs
            )
            if response is None:
                response = func(request, *args, **kwargs)
            _post_process_request(request, response, res_etag, res_last_modified)
            return response

    return inner

def _post_process_request(request, response, res_etag, res_last_modified):
    # Set relevant headers on the response if they don't already exist
    # and if the request method is safe.
    if request.method in ("GET", "HEAD"):
        if res_last_modified and not response.has_header("Last-Modified"):
            response.headers["Last-Modified"] = http_date(res_last_modified)
        if res_etag:
            response.headers.setdefault("ETag", res_etag)

def inner(request, *args, **kwargs):
    response, res_etag, res_last_modified = _pre_process_request(
        request, *args, **kwargs
    )
    if response is None:
        response = func(request, *args, **kwargs)
    _post_process_request(request, response, res_etag, res_last_modified)
    return response

